"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[99903],{99903:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/premonitory-dream.png\\"\\n          title=\\"예지몽\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"재인\\"\\n          publishedDate=\\"2009-03-31\\"\\n          isbn=\\"9788990982315\\"\\n          rating=3\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n예지몽, 유체이탈, 폴터가이스트 등 초자연적이고 신비주의적으로밖에는 해석할 수 없어 보이는 사건들을 ```갈릴레이```의 과학적 원리로 설명한다.  \\n<br>\\n단순한 트릭의 공개를 넘어 현대 사회에서 미신과 과학은 어떻게 공존하며 대립하는가라는 근원적인 질문을 던진다.  \\n<br>\\n다섯 개의 독립된 단편으로 각기 다른 미스터리와 그에 적용되는 과학 원리를 설명한다.  \\n<br>\\n작가는 현상을 맹신하기보다 의심하고, 논리적으로 사고하는 습관을 들이도록 유도하는 것 같다.  "}')}}]);